"""Conflicts nobody should pay a session for: generated files and the changelog.

Ten pull requests on one repository, and each merge leaves the nine others in
conflict — almost always in the same two places: a bundle a build writes
(`src/ponos/web/static/assets/*.js`, a lockfile) and `CHANGELOG.md`. Neither
is a decision. The first is regenerated by a command the repository already has,
the second keeps every entry from both sides; and a session started to do
either spends credits on a gesture with only one right answer (89 of the 124
merge blocks of the analysis of 12/10/2026 were that).

So a replay settles them itself, at the point where git stops. A project says
which files are generated and how to build them in a `.ponos.toml` at the root
of the repository — the file of the base, not the branch's: the branch that
rewrites the rules is not the one to apply them —

    generated = ["src/ponos/web/static/**"]
    build = "cd frontend && npm ci && npm run build"

A conflict on one of those paths takes the base's version; once the replay has
reached its end, the build runs and what it wrote is committed on top, in the
replay. The changelog needs no declaration: both sides are kept, base first.

What is left unsettled is left to git and to whoever resolves it: a conflict in
hand-written code stops the replay exactly where it stopped before, with the
settled files already off the list. Nothing here fails a replay except a build
that fails — pushing bundles that do not match their sources would be worse.
"""

from __future__ import annotations

import re
import tempfile
import tomllib
from dataclasses import dataclass, field
from pathlib import Path

from . import git

CONFIG = ".ponos.toml"
CHANGELOG = "CHANGELOG.md"

# How many times a replay may stop before it is given up on: a branch of
# two hundred commits all in conflict is not one this settles by looping.
MOST_STOPS = 200

BUILD_SECONDS = 1800


def _pattern(glob: str) -> re.Pattern[str]:
    """A glob as a path is matched against it: `**` crosses folders, `*` does not."""
    out, index = "", 0
    while index < len(glob):
        if glob.startswith("**/", index):
            out, index = out + "(?:.*/)?", index + 3
        elif glob.startswith("**", index):
            out, index = out + ".*", index + 2
        elif glob[index] == "*":
            out, index = out + "[^/]*", index + 1
        elif glob[index] == "?":
            out, index = out + "[^/]", index + 1
        else:
            out, index = out + re.escape(glob[index]), index + 1
    return re.compile(out + r"\Z")


@dataclass
class Rules:
    """What a repository declares about its generated files."""

    paths: list[str] = field(default_factory=list)
    build: str = ""

    def covers(self, name: str) -> bool:
        return any(_pattern(glob).match(name) for glob in self.paths)


def parse(text: str) -> Rules:
    """The rules a `.ponos.toml` holds — none at all when it holds nothing usable.

    A file that does not parse, or a key of the wrong type, is not a reason to
    fail a replay: it is the same as no file, and the conflict goes to a
    session as it always did.
    """
    try:
        raw = tomllib.loads(text)
    except tomllib.TOMLDecodeError:
        return Rules()
    paths = raw.get("generated", [])
    build = raw.get("build", "")
    return Rules(
        paths=[str(one) for one in paths if str(one).strip()] if isinstance(paths, list) else [],
        build=build.strip() if isinstance(build, str) else "",
    )


def rules_at(worktree: Path, onto: str) -> Rules:
    """The rules `onto` — the base — declares."""
    shown = git.git(["show", f"{onto}:{CONFIG}"], worktree)
    return parse(shown.out) if shown.ok else Rules()


def _union(worktree: Path, name: str) -> bool:
    """Both sides of a conflicted file kept, the base's lines first. False when it cannot be."""
    stages = []
    for stage in (2, 1, 3):  # ours — the base —, the ancestor, theirs
        shown = git.git(["show", f":{stage}:{name}"], worktree)
        if not shown.ok and stage != 1:
            return False  # deleted on one side: a decision, not a union
        stages.append(shown.out + "\n" if shown.out else "")
    with tempfile.TemporaryDirectory() as folder:
        files = []
        for index, text in enumerate(stages):
            one = Path(folder) / str(index)
            one.write_text(text, encoding="utf-8")
            files.append(str(one))
        merged = git.run(["git", "merge-file", "-p", "--union", *files], cwd=worktree)
    if merged.code < 0 or merged.code > 127:
        return False
    (Path(worktree) / name).write_text(merged.out + "\n", encoding="utf-8")
    return git.git(["add", "--", name], worktree).ok


def _taken(worktree: Path, name: str, rules: Rules) -> bool:
    """Settle one conflicted file if it is one of those that settle by themselves."""
    if rules.covers(name):
        # In a rebase `ours` is the base the branch is being replayed onto.
        if git.git(["checkout", "--ours", "--", name], worktree).ok:
            return git.git(["add", "--", name], worktree).ok
        # The base deleted it: so does the replay.
        return git.git(["rm", "-q", "-f", "--", name], worktree).ok
    return name == CHANGELOG and _union(worktree, name)


def rebuild(worktree: Path, onto: str, rules: Rules | None = None) -> str:
    """Run the build and commit what it wrote. Says why it could not, or nothing.

    Only when the branch changed a generated file at all, and only after a
    replay that had something to settle: a clean one needs no help. The same
    after a session resolved the hand-written conflicts of such a replay, which
    were told nothing of the generated files taken from the base.
    """
    rules = rules or rules_at(worktree, onto)
    if not rules.paths or not rules.build:
        return ""
    # What the branch changed before it was replayed: once its conflicts on a
    # bundle were settled with the base's version, the replay no longer shows
    # the bundle as changed, and it is exactly the one that must be built again.
    # `ORIG_HEAD` is where `git rebase` left the branch as it was.
    was = git.git(["rev-parse", "--verify", "ORIG_HEAD"], worktree)
    if was.ok:
        changed = git.git(["diff", "--name-only", f"{onto}...{was.out}"], worktree).out
        if not any(rules.covers(name.strip()) for name in changed.splitlines()):
            return ""
    built = git.run(["sh", "-c", rules.build], cwd=worktree, timeout=BUILD_SECONDS)
    if not built.ok:
        last = (built.err or built.out).strip().splitlines()
        return f"the build `{rules.build}` failed: {last[-1] if last else built.code}"
    specs = [f":(glob){glob}" for glob in rules.paths]
    git.git(["add", "-A", "--", *specs], worktree)
    if git.git(["diff", "--cached", "--quiet"], worktree).ok:
        return ""
    committed = git.git(
        ["commit", "-q", "-m", "Regenerate the generated files"],
        worktree,
        environment=git.identity(worktree),
    )
    return "" if committed.ok else (committed.err or committed.out)


def settle(worktree: Path, onto: str) -> str:
    """Carry a stopped replay as far as generated files and the changelog allow.

    Called with a rebase in progress, stopped on a conflict. Settles what it
    can at every stop and continues; leaves the rebase in progress, on the
    hand-written conflicts only, the moment one is met. Returns why the build
    failed once the replay has reached its end, or nothing — the caller reads
    `git.rebasing` to know whether it did.
    """
    rules = rules_at(worktree, onto)
    environment = {**git.identity(worktree), "GIT_EDITOR": "true"}
    for _ in range(MOST_STOPS):
        stuck = git.conflicted(worktree)
        left = [name for name in stuck if not _taken(worktree, name, rules)]
        if left:
            return ""
        go = git.git(["rebase", "--continue"], worktree, environment=environment)
        if go.ok:
            return rebuild(worktree, onto, rules)
        if git.conflicted(worktree):
            continue
        # Stopped on a commit that became empty once settled: nothing to keep.
        if not git.git(["diff", "--cached", "--quiet"], worktree).ok:
            return ""
        skipped = git.git(["rebase", "--skip"], worktree, environment=environment)
        if skipped.ok:
            return rebuild(worktree, onto, rules)
        if not git.conflicted(worktree):
            return ""
    return ""
